import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BWTY_seE.js";const g=JSON.parse('{"title":"AI 动态 · 2026-11-13","description":"","frontmatter":{"title":"AI 动态 · 2026-11-13","date":"2026-11-13T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-13.md","filePath":"news/2026-11/ai-news-2026-11-13.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-13.md"};function r(o,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-动态-·-2026-11-13" tabindex="-1">AI 动态 · 2026-11-13 <a class="header-anchor" href="#ai-动态-·-2026-11-13" aria-label="Permalink to &quot;AI 动态 · 2026-11-13&quot;">​</a></h1><blockquote><p>截至 2026-11-13。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>今日最大变量来自英伟达：黄仁勋在执掌33年后辞职、Colette Kress 出任临时CEO，国会调查与芯片追踪争议同步发酵，AI算力格局进入不确定期。</li><li>模型侧Google一次性把Gemini 4 Hydrogen推向搜索、Gemini应用、AI Studio与API，主打智能体工作流与低价，Anthropic则补上安全评测与常驻Agent方法论。</li><li>产品与工具层，OpenAI推出ChatGPT Wallet让Agent在用户授权下完成支付，开源侧llama.cpp发布v1.0.0、CopilotKit开源带治理的OpenBot 1.0，Agent工程化继续加速。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="头条-·-openai推出chatgpt-wallet-让agent在用户授权下完成支付" tabindex="-1">头条 · OpenAI推出ChatGPT Wallet，让Agent在用户授权下完成支付 <a class="header-anchor" href="#头条-·-openai推出chatgpt-wallet-让agent在用户授权下完成支付" aria-label="Permalink to &quot;头条 · OpenAI推出ChatGPT Wallet，让Agent在用户授权下完成支付&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/5cd0b90e7e1c.webp" alt="配图"></p><p>OpenAI发布ChatGPT Wallet，为ChatGPT Work、Codex与dots中的Agent提供安全的支付能力：购买需经用户批准，并沿用现有银行卡保护机制。官方称这是与卡组织、银行和商户共同构建的可信Agent支付方案。对读者：若在做Agent商业化，可提前研究其授权与风控模型，把「人工确认」设计进支付链路以降低纠纷风险。</p><p class="news-entry-source"><a href="https://openai.com/index/introducing-chatgpt-wallet" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude的duet-agent有点神经质-但意外地好用" tabindex="-1">Claude的Duet Agent有点神经质，但意外地好用 <a class="header-anchor" href="#claude的duet-agent有点神经质-但意外地好用" aria-label="Permalink to &quot;Claude的Duet Agent有点神经质，但意外地好用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/04b9ad5579cd.jpg" alt="配图"></p><p>The Verge 实测Anthropic面向消费者的Agent产品Claude Duet，认为它比Instinct、Meta的Muse、OpenAI的Dots更偏工作场景，能帮忙补上容易遗漏的细节。评测形容它「有点神经质」但确实能兜住问题。对读者：选消费级Agent时别只看演示效果，重点测它在长任务中主动纠错与提醒的能力。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1032518/claude-duet-ai-agent-hands-on" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic发布常驻agent构建指南-跨会话持续运行的核心原语" tabindex="-1">Anthropic发布常驻Agent构建指南：跨会话持续运行的核心原语 <a class="header-anchor" href="#anthropic发布常驻agent构建指南-跨会话持续运行的核心原语" aria-label="Permalink to &quot;Anthropic发布常驻Agent构建指南：跨会话持续运行的核心原语&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/7a06f9093a77.webp" alt="配图"></p><p>Claude博客发布《Building always-on agents》指南，指出常驻Agent会无限期运行，并自行决定在多个会话之间何时、以何种方式行动。文章逐一讲解其核心原语及组合方式。对读者：做长时运行Agent前先想清楚状态持久化、触发条件与失败恢复三件事，否则调试成本会指数上升。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/building-always-on-agents" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="muse的ai现在能替用户拨打美国商家电话-但要付费" tabindex="-1">Muse的AI现在能替用户拨打美国商家电话，但要付费 <a class="header-anchor" href="#muse的ai现在能替用户拨打美国商家电话-但要付费" aria-label="Permalink to &quot;Muse的AI现在能替用户拨打美国商家电话，但要付费&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/8e145d9fb51c.webp" alt="配图"></p><p>TechCrunch报道，Muse的AI已可向美国企业发起外呼电话，但该能力并非免费，需要付费使用。这是消费级Agent从「屏幕内操作」走向「真实世界动作」的又一步。对读者：外呼类Agent涉及合规与品牌风险，接入前应确认通话录音、身份披露与失败转人工策略。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/12/muse-can-now-place-calls-to-u-s-businesses-if-you-pay/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="elevenlabs推出新应用-把会议记录与听写合二为一" tabindex="-1">ElevenLabs推出新应用，把会议记录与听写合二为一 <a class="header-anchor" href="#elevenlabs推出新应用-把会议记录与听写合二为一" aria-label="Permalink to &quot;ElevenLabs推出新应用，把会议记录与听写合二为一&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e971e6b318c5.webp" alt="配图"></p><p>TechCrunch报道，ElevenLabs发布名为ElevenAI的新应用，同时提供会议记录与听写功能，面向团队与企业用户。语音厂商正从API供应商向办公协作产品延伸。对读者：评估会议AI工具时重点比对转写准确率、说话人分离与数据留存策略，而非只看界面。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/13/elevenlabs-new-app-combines-meeting-note-taking-and-dictation-for-teams/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google发布gemini-4-hydrogen-比gemini-3-8-flash快2-5倍" tabindex="-1">Google发布Gemini 4 Hydrogen：比Gemini 3.8 Flash快2.5倍 <a class="header-anchor" href="#google发布gemini-4-hydrogen-比gemini-3-8-flash快2-5倍" aria-label="Permalink to &quot;Google发布Gemini 4 Hydrogen：比Gemini 3.8 Flash快2.5倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-13">2026-11-13</time></p><p>MarkTechPost报道，Gemini 4 Hydrogen定位快速Agent模型，具备100万token上下文窗口、4档思考层级，定价为每百万token输入1.50美元、输出7.50美元。Google给出的数据是Artificial Analysis得分51、Terminal-Bench 4.1上57%。对读者：长上下文加低价的组合适合做Agent主循环，但需按任务实测思考层级对成本的影响。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/13/google-gemini-4-hydrogen/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="google新gemini模型更擅长理解复杂问题" tabindex="-1">Google新Gemini模型更擅长理解复杂问题 <a class="header-anchor" href="#google新gemini模型更擅长理解复杂问题" aria-label="Permalink to &quot;Google新Gemini模型更擅长理解复杂问题&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/709f3df39f75.jpg" alt="配图"></p><p>The Verge报道，Gemini 4 Hydrogen可拆解「包含多个部分、含难懂拼写错误或高度具体」的问题并逐段作答，发布当天即上线搜索、Gemini应用、Google AI Studio全部层级、Gemini API、Gemini for business，以及面向Pro与Ultra订阅者的Google Antigravity。Google搜索产品VP Robby Stein称其已成为AI Mode的默认模型。对读者：若产品依赖搜索增强，可优先在AI Mode路径上做A/B，观察复杂查询的完成率变化。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1032505/google-search-ai-mode-gemini-4-hydrogen" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="llm-gemini-0-37发布-gemini-4定价体系让人困惑" tabindex="-1">llm-gemini 0.37发布，Gemini 4定价体系让人困惑 <a class="header-anchor" href="#llm-gemini-0-37发布-gemini-4定价体系让人困惑" aria-label="Permalink to &quot;llm-gemini 0.37发布，Gemini 4定价体系让人困惑&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/abe6f1fb55b3.jpg" alt="配图"></p><p>Simon Willison发布llm-gemini 0.37，并梳理Gemini 4家族定价：Carbon与Argon在2026年11月30日前均为输入2.00美元、缓存输入0.10美元、输出10.00美元，12月1日起翻倍为4.00/0.20/20.00美元；Hydrogen为1.50/0.075/7.50美元。他指出Hydrogen与更大杯的兄弟型号价差并不大。对读者：跨年项目务必把12月1日的涨价节点写进成本模型，避免预算按旧价估算。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/12/llm-gemini/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="liquid-ai开源liquidcodec-7400万参数流式音频编解码器" tabindex="-1">Liquid AI开源LiquidCodec：7400万参数流式音频编解码器 <a class="header-anchor" href="#liquid-ai开源liquidcodec-7400万参数流式音频编解码器" aria-label="Permalink to &quot;Liquid AI开源LiquidCodec：7400万参数流式音频编解码器&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-13">2026-11-13</time></p><p>MarkTechPost报道，Liquid AI发布约7400万参数的流式音频编解码器LiquidCodec，为LFM3-Audio-2B与LFM3-Omni-2B提供底层支持。它以12.5Hz、12个码本运行，在单CPU线程上编码速度约为实时的361倍。对读者：做实时语音交互时，这类轻量编解码器能显著降低端侧算力门槛，值得纳入选型对比。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/12/liquid-ai-liquidcodec-streaming-audio-codec/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="llama-cpp发布v1-0-0-为本地ai生态打下更强地基" tabindex="-1">llama.cpp发布v1.0.0：为本地AI生态打下更强地基 <a class="header-anchor" href="#llama-cpp发布v1-0-0-为本地ai生态打下更强地基" aria-label="Permalink to &quot;llama.cpp发布v1.0.0：为本地AI生态打下更强地基&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/57554d80b4b2.png" alt="配图"></p><p>Hugging Face博客刊出ggml-org的公告，llama.cpp迎来v1.0.0版本，被定位为本地AI生态「更强的基础」。这一版本号标志着这个广泛使用的本地推理项目进入新的稳定阶段。对读者：长期锁定旧版本做端侧推理的团队，可评估升级到v1.0.0以获取更稳定的接口与后续维护支持。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/ggml-org/llama-cpp-v1" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="copilotkit开源openbot-1-0-mit许可、可自托管、内置治理" tabindex="-1">CopilotKit开源OpenBot 1.0：MIT许可、可自托管、内置治理 <a class="header-anchor" href="#copilotkit开源openbot-1-0-mit许可、可自托管、内置治理" aria-label="Permalink to &quot;CopilotKit开源OpenBot 1.0：MIT许可、可自托管、内置治理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-13">2026-11-13</time></p><p>MarkTechPost报道，CopilotKit发布OpenBot 1.0，这是一个MIT许可、可自托管的AI同事工作空间。企业自带Agent、模型与基础设施，每个Bot动作都要经过策略检查并写入审计轨迹。对读者：需要合规留痕的内部Agent场景，可直接以它为底座，省去自建策略与审计层的工作量。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/12/copilotkit-openbot-1-0-open-source-ai-coworker/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-一次编写、随处运行的agent-skills实践指南" tabindex="-1">GitHub：一次编写、随处运行的Agent Skills实践指南 <a class="header-anchor" href="#github-一次编写、随处运行的agent-skills实践指南" aria-label="Permalink to &quot;GitHub：一次编写、随处运行的Agent Skills实践指南&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c5830d902889.png" alt="配图"></p><p>GitHub博客指出，Agent Skills把可复用的工程工作沉淀为团队可评审、可复用的文件，而工具、项目上下文与权限仍由运行它的宿主决定。文章给出跨Agent复用的落地方法。对读者：把团队约定写成Skill文件比反复调提示词更可持续，建议从代码评审与发布检查这两类高频流程开始。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/build-once-run-on-any-agent-a-practical-guide-to-agent-skills/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="github公布2026年10月可用性报告-共8起事故" tabindex="-1">GitHub公布2026年10月可用性报告：共8起事故 <a class="header-anchor" href="#github公布2026年10月可用性报告-共8起事故" aria-label="Permalink to &quot;GitHub公布2026年10月可用性报告：共8起事故&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-11-13">2026-11-13</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e367118e7bc3.webp" alt="配图"></p><p>GitHub博客发布10月可用性报告，称当月共发生8起导致GitHub服务性能下降的事故。报告是评估平台稳定性的常规参考。对读者：关键CI/CD链路应配置镜像与本地缓存，避免单一代码托管平台的抖动直接阻断发布。</p><p class="news-entry-source"><a href="https://github.blog/news-insights/company-news/github-availability-report-october-2026/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="shadcn的下一个动作-ui-sdk" tabindex="-1">shadcn的下一个动作：UI SDK <a class="header-anchor" href="#shadcn的下一个动作-ui-sdk" aria-label="Permalink to &quot;shadcn的下一个动作：UI SDK&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">React Status</span><time datetime="2026-11-13">2026-11-13</time></p><p>React Status第497期聚焦shadcn的新方向UI SDK，同时收录声明式拖拽库Dragology（面向SVG界面的实验性React库，通过声明可能结果让库推导交互）、元框架基准测试，以及在DevTools控制台里运行React应用等话题。对读者：组件库正从「复制粘贴源码」走向SDK化分发，评估shadcn生态时需关注其版本升级与依赖治理策略。</p><p class="news-entry-source"><a href="https://react.statuscode.com/issues/497" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const m=a(s,[["render",r]]);export{g as __pageData,m as default};
